public class METVendorRebateOffRemittanceCalcTaskService extends METSysOperationTaskService
{

    guid queueId;
    InventSiteId siteId;
    METVendorRebateOffRemittanceCalcTaskContract contract;

}

Method.Source:
/// <summary>
///  Initializes the object.
/// </summary>
protected void initialise()
{


    super();

    // get the topPickingProcessId from the contract
    contract = dataContract as METVendorRebateOffRemittanceCalcTaskContract;
    queueId = contract.parmTopPickingProcessId();
}

/// <summary>
///
/// </summary>
/// <param name = "_readPast"></param>
protected void processTask(boolean _readPast)
{
    METVendorRebateOffRemittanceCalcStaging transStaging;
    ttsbegin;
    while (this.getDataFromTopPickingQueue(queueId, _readPast))
    {
        LedgerJournalTable journalTable = this.findOrCreateJournal();
        LedgerJournalName journalName = LedgerJournalName::find(journalTable.JournalName);
        MarkupTable markupTable = MarkupTable::find(MarkupModuleType::Vend, transStaging.ChargeCode);

        if(contract.parmGroupByChargeCode() && contract.parmGroupByDepartment())
        {
             while select sum(ChargeAmount) from transStaging
                group by ChargeCode, Department
                where transStaging.ProcessId == queueId
                && transStaging.SiteId == siteId
            {
                LedgerJournalTrans trans;
                trans.clear();
                trans.initValue();
                trans.OffsetAccountType = journalName.OffsetAccountType;
                trans.OffsetLedgerDimension = journalName.OffsetLedgerDimension;
                trans.JournalNum = journalTable.JournalNum;
                trans.AccountType = LedgerJournalACType::Ledger;
                trans.LedgerDimension = markupTable.VendorLedgerDimension;
                trans.AmountCurCredit = transStaging.ChargeAmount;
                trans.OffsetDefaultDimension = journalName.DefaultDimension;

                if(trans.validateWrite())
                {
                    trans.insert();
                }
            }
        }
        else if(contract.parmGroupByChargeCode())
        {
            while select sum(ChargeAmount) from transStaging
                group by ChargeCode
                where transStaging.ProcessId == queueId
                && transStaging.SiteId == siteId
            {
                LedgerJournalTrans trans;
                trans.clear();
                trans.initValue();
                trans.OffsetAccountType = journalName.OffsetAccountType;
                trans.OffsetLedgerDimension = journalName.OffsetLedgerDimension;
                trans.JournalNum = journalTable.JournalNum;
                trans.AccountType = LedgerJournalACType::Ledger;
                trans.LedgerDimension = markupTable.VendorLedgerDimension;
                trans.AmountCurCredit = transStaging.ChargeAmount;
                trans.OffsetDefaultDimension = journalName.DefaultDimension;

                if(trans.validateWrite())
                {
                    trans.insert();
                }
            }
        }
        else if(contract.parmGroupByDepartment())
        {
            while select sum(ChargeAmount) from transStaging
                group by Department
                where transStaging.ProcessId == queueId
                && transStaging.SiteId == siteId
            {
                LedgerJournalTrans trans;
                trans.clear();
                trans.initValue();
                trans.OffsetAccountType = journalName.OffsetAccountType;
                trans.OffsetLedgerDimension = journalName.OffsetLedgerDimension;
                trans.JournalNum = journalTable.JournalNum;
                trans.AccountType = LedgerJournalACType::Ledger;
                trans.LedgerDimension = markupTable.VendorLedgerDimension;
                trans.AmountCurCredit = transStaging.ChargeAmount;
                trans.OffsetDefaultDimension = journalName.DefaultDimension;

                if(trans.validateWrite())
                {
                    trans.insert();
                }
            }
        }
        LedgerJournalCheckPost::newLedgerJournalTable(journalTable).run();

        VendPackingSlipTrans packingSlipTrans;

        update_recordset packingslipTrans
            setting METRemittanceJournalId = journalTable.JournalNum
            join transStaging
            where transStaging.PackingSlipTransRecId == packingSlipTrans.recid
            && transStaging.SiteId == siteId
            && transStaging.ProcessId == queueId;

        delete_from transStaging 
            where transStaging.SiteId == siteId 
                && transStaging.ProcessId == queueId;

        ttscommit;
    }
}

private LedgerJournalTable findOrCreateJournal()
{
    LedgerJournalTable journalTable;

    select firstonly journalTable
        where journalTable.METSiteId == siteId
        && journalTable.METAsOfDate == contract.parmAsOnDate();

    if(!journalTable)
    {
        journalTable.clear();
        journalTable.JournalName = METVendParameters::find().RebateAccrualJournalName;
        journalTable.initFromLedgerJournalName();
        journalTable.Name = 'Vendor rebate accrual for the period Feb2025';
        journalTable.METSiteId = siteId;
        journalTable.METAsOfDate = contract.parmAsOnDate();
        journalTable.ReverseDate = contract.parmReversalDate();
        journalTable.ReverseEntry = NoYes::Yes;

        journalTable.insert();
    }

    return journalTable;
}

/// <summary>
/// Gets data to reserve event orders.
///</summary>
/// <param name = "_processId">Guid created and added in the contract <c>METReserveEventOrdersContract</c>.</param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>True, if data is retrieved from the queue; otherwise; false.</returns>
private boolean getDataFromTopPickingQueue(guid _processId, boolean _readPast)
{
    #OCCRetryCount

    METVendorRebateSiteJournalStaging topPickingQueue;
    int                        backOffWait;

    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    topPickingQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock topPickingQueue
            where topPickingQueue.ProcessId == _processId;

        if (topPickingQueue.RecId)
        {
            siteId = topPickingQueue.SiteId;

            topPickingQueue.delete();
        }
        else
        {
            siteId = '';
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return (siteId != '');
}
